declare(strict_types=1);
function arg(string $name): ?string { global $argv; $i=array_search($name,$argv,true); return $i===false?null:($argv[$i+1]??null); }
function pathName(array $path): string { return implode('',array_map(static fn($v,$i)=>$i===0?(string)$v:'['.$v.']',$path,array_keys($path))); }
