$results=[];foreach($document['configs']??[] as $index=>$config){$id=$runId.'-replay-'.$index.'-'.substr(hash('sha256',$config['config_id']),0,12);$request=$config['request'];foreach($config['discovered_parameters'] as $p){if(($p['effective_source']??null)===null)continue;$bucket=$p['effective_source']==='query'?'query':($p['effective_source']==='cookie'?'cookies':'body');$request[$bucket][pathName($p['path'])]=$p['marker_id'];}$url=$base.$request['path'].($request['query']?('?'.http_build_query($request['query'],'','&',PHP_QUERY_RFC3986)):'');$bodyFile=tempnam(sys_get_temp_dir(),'p9body');$cmd=['curl','-sS','--max-time','20','-o',$bodyFile,'-w','%{http_code}','-X',$request['method'],'-H','X-Fuzzer-Covid: '.$id,'-H','X-Phase9-Run-ID: '.$runId];foreach($request['cookies'] as $k=>$v){$cmd[]='-b';$cmd[]=$k.'='.$v;}if($jar&&($config['authentication']['requires_auth']??false)){$cmd[]='-b';$cmd[]=$jar;}foreach($request['body'] as $k=>$v){$cmd[]='--data-urlencode';$cmd[]=$k.'='.$v;}$cmd[]=$url;$status=(int)trim((string)shell_exec(implode(' ',array_map('escapeshellarg',$cmd))));$artifactFile=$artifactDir.'/'.$id.'.json';for($i=0;$i<200&&!is_file($artifactFile);$i++)usleep(100000);$found=is_file($artifactFile);try{$artifact=$found?json_decode((string)file_get_contents($artifactFile),true,512,JSON_THROW_ON_ERROR):[];$response=json_decode((string)file_get_contents($bodyFile),true,512,JSON_THROW_ON_ERROR);}catch(Throwable){$artifact=[];$response=[];}$mismatches=[];$valid=0;foreach($config['discovered_parameters'] as $p){$event=eventMatches($artifact,$p,$config['callback']);$marker=hasMarker($response['data']['phase9Markers']??[],$p['marker_id']);if($event&&$marker)$valid++;else $mismatches[]=['path'=>$p['path'],'expected_placement'=>$p['effective_source']??null,'event'=>$event,'marker_observed'=>$marker];}$reached=(bool)array_filter($artifact['events']??[],static fn($e)=>($e['callback_context']['root_callback']??null)===($config['callback']));$expected=count($config['discovered